package com.campusevents.model;
public abstract class User {private final int userId;private final String name,email,passwordHash;protected User(int id,String name,String email,String hash){if(name==null||name.isBlank()||email==null||!email.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))throw new IllegalArgumentException("Invalid name or email.");this.userId=id;this.name=name.trim();this.email=email.trim().toLowerCase();this.passwordHash=hash;}public int getUserId(){return userId;}public String getName(){return name;}public String getEmail(){return email;}public String getPasswordHash(){return passwordHash;}public abstract String getRole();public String getDisplayLabel(){return name+" ("+getRole()+")";}}
